        (79, 2, 9, 'g34-l09', 'korean', 'listening', 'intermediate', NULL, '{"prompt":"민지가 준호에게 전화를 한 까닭은 무엇입니까?","audioUrl":"/diagnostic-assets/g34/korean/listening/q09.mp3","stimulusText":""}', '[{"id":"1","text":"준호에게 휴대전화를 빌리고 싶어서."},{"id":"2","text":"사진에 대한 준호의 생각을 듣고 싶어서."},{"id":"3","text":"내일 만날 장소를 정하려고."},{"id":"4","text":"숙제를 물어보려고."}]', '2', 6.0, 21, NULL),
