        (92, 2, 22, 'g34-r07', 'daily', 'reading', 'beginner', NULL, '{"prompt":"그림을 바르게 설명한 것은 무엇입니까?","stimulusText":"","imageUrl":"/diagnostic-assets/g34/daily/reading/q07.png"}', '[{"id":"1","text":"축구를 합니다."},{"id":"2","text":"노래를 부릅니다."},{"id":"3","text":"그림을 그립니다."},{"id":"4","text":"그림책을 읽습니다."}]', '4', 4.0, NULL, 30),
        (93, 2, 23, 'g34-r08', 'korean', 'reading', 'beginner', NULL, '{"prompt":"윗글과 가장 관계있는 말은 무엇입니까?","stimulusText":"나는 오늘 수업 시간에 친구들 앞에서 말했습니다. 선생님께서 칭찬해 주셨습니다."}', '[{"id":"1","text":"수업"},{"id":"2","text":"생일"},{"id":"3","text":"시험"},{"id":"4","text":"여행"}]', '1', 4.0, NULL, NULL),
        (94, 2, 24, 'g34-r09', 'math', 'reading', 'beginner', NULL, '{"prompt":"앞에 제시된 것과 가장 관계있는 것은 무엇입니까?","stimulusText":"","word":"정사각형, 직사각형, 직각삼각형"}', '[{"id":"1","text":"과일"},{"id":"2","text":"동물"},{"id":"3","text":"도형"},{"id":"4","text":"음식"}]', '3', 4.0, NULL, NULL),
        (95, 2, 25, 'g34-r10', 'daily', 'reading', 'beginner', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"영희가 민호에게 쓴 생일 축하 편지이다."},{"id":"2","text":"영희가 민호에게 보낸 생일 초대 쪽지이다."},{"id":"3","text":"민호가 영희에게 보낸 초대 쪽지이다."},{"id":"4","text":"영희는 민호에게 줄 케이크를 준비했다."}]', '2', 4.0, NULL, NULL),
        (96, 2, 26, 'g34-r11', 'science', 'reading', 'intermediate', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"㉯ → ㉮ → ㉰ → ㉱"},{"id":"2","text":"㉰ → ㉯ → ㉮ → ㉱"},{"id":"3","text":"㉰ → ㉮ → ㉯ → ㉱"},{"id":"4","text":"㉯ → ㉰ → ㉮ → ㉱"}]', '4', 6.0, NULL, NULL),
        (97, 2, 27, 'g34-r12', 'social', 'reading', 'intermediate', NULL, '{"prompt":"다음 글을 바르게 이해한 것은 무엇입니까?","stimulusText":"우리 가족은 일요일에 시장과 백화점에 갔다. 시장은 백화점에 비해 값이 쌌다. 그래서 어머니는 시장에서 과일을 사셨다."}', '[{"id":"1","text":"어머니는 시장에서 과일을 사셨다."},{"id":"2","text":"어머니는 백화점에서 과일을 사셨다."},{"id":"3","text":"시장은 백화점보다 값이 비쌌다."},{"id":"4","text":"우리 가족은 토요일에 시장에 갔다."}]', '1', 6.0, NULL, NULL),
        (98, 2, 28, 'g34-r13', 'daily', 'reading', 'intermediate', NULL, '{"prompt":"내가 친구에게 돈을 빌린 까닭은 무엇입니까?","stimulusText":"어제 학교에 가는 길에 비가 많이 왔다. 우산이 없어서 편의점에 가서 우산을 사려고 했다. 그런데 계산하려고 보니 지갑을 집에 두고 왔다. 마침 같은 반 친구를 만나서 이야기하며 돈을 빌렸다."}', '[{"id":"1","text":"우산이 너무 비싸서."},{"id":"2","text":"친구가 돈이 많아서."},{"id":"3","text":"지갑을 집에 두고 와서."},{"id":"4","text":"편의점이 학교에서 멀어서."}]', '3', 6.0, NULL, NULL),
        (99, 2, 29, 'g34-r14', 'math', 'reading', 'intermediate', NULL, '{"prompt":"우리 반 친구들이 좋아하는 과일에 대해 조사하여 그림그래프로 나타냈습니다. (● 한 개는 1명입니다.) 그림그래프를 바르게 이해한 것은 무엇입니까?","stimulusText":"","stimulusTable":{"headers":["과일","학생 수"],"rows":[["사과","●●●●●●●●"],["딸기","●●●●"],["포도","●●●●●●"],["바나나","●●●"]]}}', '[{"id":"1","text":"딸기를 좋아하는 학생은 포도에 비해 많다."},{"id":"2","text":"사과를 좋아하는 학생이 가장 많다."},{"id":"3","text":"바나나를 좋아하는 학생은 4명이다."},{"id":"4","text":"포도를 좋아하는 학생은 사과보다 많다."}]', '2', 6.0, NULL, NULL),
        (100, 2, 30, 'g34-r15', 'korean', 'reading', 'intermediate', NULL, '{"prompt":"윗글의 중심 이야기는 무엇입니까?","stimulusText":"나는 휴대전화로 가족 사진을 찍었다. 사진 속 동생의 표정이 아주 재미있었다. 사진을 보며 가족과 함께 웃었다. 나는 사진에 대해 느낌을 그림으로 그려 보았다."}', '[{"id":"1","text":"가족 사진을 찍고 느낌을 나눈 일"},{"id":"2","text":"동생과 다투었던 일"},{"id":"3","text":"휴대전화를 새로 산 일"},{"id":"4","text":"그림 대회에서 상을 받은 일"}]', '1', 6.0, NULL, NULL),
        (101, 2, 31, 'g34-r16', 'korean', 'reading', 'advanced', NULL, '{"prompt":"윗글에서 밑줄 친 ㉮~㉱ 중 가리키는 것이 다른 하나는 무엇입니까?","stimulusText":"독서 시간에 나는 동화책을 한 권 읽었다. 이 책의 ㉮등장인물은 남자아이이다. ㉯그 아이는 용감하며 마음이 따뜻하다. 나는 독서가 끝난 뒤 ㉰그 아이에 대해 감상문을 썼다. 선생님께서는 ㉱그 글을 칭찬해 주셨다.","promptSpans":[{"text":"윗글에서 밑줄 친 ㉮~㉱ 중 가리키는 것이 ","style":"plain"},{"text":"다른","style":"strong"},{"text":" 하나는 무엇입니까?","style":"plain"}],"stimulusSpans":[{"text":"독서 시간에 나는 동화책을 한 권 읽었다. 이 책의 ","style":"plain"},{"text":"㉮등장인물","style":"underline"},{"text":"은 남자아이이다. ","style":"plain"},{"text":"㉯그 아이","style":"underline"},{"text":"는 용감하며 마음이 따뜻하다. 나는 독서가 끝난 뒤 ","style":"plain"},{"text":"㉰그 아이","style":"underline"},{"text":"에 대해 감상문을 썼다. 선생님께서는 ","style":"plain"},{"text":"㉱그 글","style":"underline"},{"text":"을 칭찬해 주셨다.","style":"plain"}]}', '[{"id":"1","text":"㉮"},{"id":"2","text":"㉯"},{"id":"3","text":"㉰"},{"id":"4","text":"㉱"}]', '4', 6.0, NULL, NULL),
        (102, 2, 32, 'g34-r17', 'social', 'reading', 'advanced', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"학교 급식 메뉴를 안내한다."},{"id":"2","text":"그림 대회 결과를 발표한다."},{"id":"3","text":"투표에 참여하도록 권유한다."},{"id":"4","text":"학급 회의 결과를 알린다."}]', '3', 6.0, NULL, NULL),
        (103, 2, 33, 'g34-r18', 'social', 'reading', 'advanced', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"투표한 학생의 이름"},{"id":"2","text":"선거가 열리는 장소"},{"id":"3","text":"지난해 투표한 학생 수"},{"id":"4","text":"선거의 결과"}]', '2', 6.0, NULL, NULL),
        (104, 2, 34, 'g34-r19', 'korean', 'reading', 'advanced', NULL, '{"prompt":"윗글에서 밑줄 친 ㉮~㉱ 중 중심 문장은 무엇입니까?","stimulusText":"㉮운동은 우리 몸을 건강하게 한다. ㉯규칙적으로 운동하면 뼈와 근육이 강해진다. ㉰운동을 할수록 기분이 좋아지고 잠도 잘 잔다. ㉱또 운동을 하면 쌓였던 피로가 풀린다.","stimulusSpans":[{"text":"㉮운동은 우리 몸을 건강하게 한다.","style":"underline"},{"text":" ","style":"plain"},{"text":"㉯규칙적으로 운동하면 뼈와 근육이 강해진다.","style":"underline"},{"text":" ","style":"plain"},{"text":"㉰운동을 할수록 기분이 좋아지고 잠도 잘 잔다.","style":"underline"},{"text":" ","style":"plain"},{"text":"㉱또 운동을 하면 쌓였던 피로가 풀린다.","style":"underline"}]}', '[{"id":"1","text":"㉮"},{"id":"2","text":"㉯"},{"id":"3","text":"㉰"},{"id":"4","text":"㉱"}]', '1', 6.0, NULL, NULL),
        (105, 2, 35, 'g34-r20', 'math', 'reading', 'advanced', NULL, '{"prompt":"윗글에서 알 수 있는 것은 무엇입니까?","stimulusText":"평행사변형은 마주 보는 두 쌍의 변이 서로 평행한 사각형이다. 평행사변형은 마주 보는 변의 길이가 같으므로 둘레를 구할 때에는 두 변의 길이만 알면 된다."}', '[{"id":"1","text":"평행사변형은 네 변의 길이가 모두 다르다."},{"id":"2","text":"평행사변형은 마주 보는 변이 서로 만난다."},{"id":"3","text":"평행사변형은 각이 모두 직각이다."},{"id":"4","text":"평행사변형은 마주 보는 변의 길이가 같다."}]', '4', 6.0, NULL, NULL),
        (106, 3, 1, 'g56-l01', 'daily', 'listening', 'beginner', NULL, '{"prompt":"들려주는 낱말을 바르게 적은 것은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/daily/listening/q01.mp3","stimulusText":""}', '[{"id":"1","text":"사람"},{"id":"2","text":"사탕"},{"id":"3","text":"사다"},{"id":"4","text":"사랑"}]', '4', 4.0, 31, NULL),
        (107, 3, 2, 'g56-l02', 'math', 'listening', 'beginner', NULL, '{"prompt":"들려주는 말에 맞는 그림은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/math/listening/q02.mp3","stimulusText":""}', '[{"id":"1","text":"1번 그림","imageUrl":"/diagnostic-assets/g56/math/listening/q02-option-1.png"},{"id":"2","text":"2번 그림","imageUrl":"/diagnostic-assets/g56/math/listening/q02-option-2.png"},{"id":"3","text":"3번 그림","imageUrl":"/diagnostic-assets/g56/math/listening/q02-option-3.png"},{"id":"4","text":"4번 그림","imageUrl":"/diagnostic-assets/g56/math/listening/q02-option-4.png"}]', '1', 4.0, 36, NULL),
        (108, 3, 3, 'g56-l03', 'daily', 'listening', 'beginner', NULL, '{"prompt":"들려주는 말들과 가장 관련 있는 곳은 어디입니까?","audioUrl":"/diagnostic-assets/g56/daily/listening/q03.mp3","stimulusText":""}', '[{"id":"1","text":"약국"},{"id":"2","text":"서점"},{"id":"3","text":"빵집"},{"id":"4","text":"극장"}]', '3', 6.0, 37, NULL),
        (109, 3, 4, 'g56-l04', 'daily', 'listening', 'beginner', NULL, '{"prompt":"나는 친구에게 무슨 말을 해야 할까요?","audioUrl":"/diagnostic-assets/g56/daily/listening/q04.mp3","stimulusText":""}', '[{"id":"1","text":"연필을 잃어버렸어."},{"id":"2","text":"연필을 빌려 줄래?"},{"id":"3","text":"연필이 비싸네."},{"id":"4","text":"연필을 버리지 마."}]', '2', 4.0, 38, NULL),
        (110, 3, 5, 'g56-l05', 'social', 'listening', 'beginner', NULL, '{"prompt":"들려주는 말들과 가장 관련 있는 대륙은 어디입니까?","audioUrl":"/diagnostic-assets/g56/social/listening/q05.mp3","stimulusText":""}', '[{"id":"1","text":"아프리카"},{"id":"2","text":"유럽"},{"id":"3","text":"오세아니아"},{"id":"4","text":"아시아"}]', '4', 4.0, 39, NULL),
        (111, 3, 6, 'g56-l06', 'korean', 'listening', 'beginner', NULL, '{"prompt":"대화에서 알 수 있는 것은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/korean/listening/q06.mp3","stimulusText":""}', '[{"id":"1","text":"여자는 내일 발표를 한다."},{"id":"2","text":"남자는 사진을 찍으러 간다."},{"id":"3","text":"남자는 내일 가족 사진을 보여 주고 발표할 것이다."},{"id":"4","text":"수업은 이미 끝났다."}]', '3', 6.0, 40, NULL),
        (112, 3, 7, 'g56-l07', 'science', 'listening', 'beginner', NULL, '{"prompt":"선생님의 말씀에 맞는 그림은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/science/listening/q07.mp3","stimulusText":""}', '[{"id":"1","text":"1번 그림","imageUrl":"/diagnostic-assets/g56/science/listening/q07-option-1.png"},{"id":"2","text":"2번 그림","imageUrl":"/diagnostic-assets/g56/science/listening/q07-option-2.png"},{"id":"3","text":"3번 그림","imageUrl":"/diagnostic-assets/g56/science/listening/q07-option-3.png"},{"id":"4","text":"4번 그림","imageUrl":"/diagnostic-assets/g56/science/listening/q07-option-4.png"}]', '1', 6.0, 45, NULL),
        (113, 3, 8, 'g56-l08', 'daily', 'listening', 'beginner', NULL, '{"prompt":"두 사람이 이야기하는 곳은 어디입니까?","audioUrl":"/diagnostic-assets/g56/daily/listening/q08.mp3","stimulusText":""}', '[{"id":"1","text":"우체국"},{"id":"2","text":"도서관"},{"id":"3","text":"서점"},{"id":"4","text":"식당"}]', '2', 8.0, 46, NULL),
        (114, 3, 9, 'g56-l09', 'korean', 'listening', 'intermediate', NULL, '{"prompt":"민지가 준호에게 전화를 한 까닭은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/korean/listening/q09.mp3","stimulusText":""}', '[{"id":"1","text":"준호에게 숙제를 물어보려고."},{"id":"2","text":"내일 만날 시간을 정하려고."},{"id":"3","text":"뉴스 내용에 대해 이야기하고 사진을 공유하려고."},{"id":"4","text":"인터넷 사용법을 가르쳐 주려고."}]', '3', 6.0, 47, NULL),
        (115, 3, 10, 'g56-l10', 'science', 'listening', 'intermediate', NULL, '{"prompt":"다음은 무엇에 관한 설명입니까?","audioUrl":"/diagnostic-assets/g56/science/listening/q10.mp3","stimulusText":""}', '[{"id":"1","text":"호흡"},{"id":"2","text":"소화"},{"id":"3","text":"배설"},{"id":"4","text":"광합성"}]', '4', 10.0, 48, NULL),
        (116, 3, 11, 'g56-l11', 'social', 'listening', 'intermediate', NULL, '{"prompt":"다음 설명에서 가장 중요한 말은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/social/listening/q11.mp3","stimulusText":""}', '[{"id":"1","text":"한자"},{"id":"2","text":"훈민정음"},{"id":"3","text":"백성"},{"id":"4","text":"중국"}]', '2', 10.0, 49, NULL),
        (117, 3, 12, 'g56-l12', 'math', 'listening', 'intermediate', NULL, '{"prompt":"남자의 말 다음에 여자가 할 말은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/math/listening/q12.mp3","stimulusText":""}', '[{"id":"1","text":"점수를 모두 더한 다음에 시험 횟수로 나누면 돼."},{"id":"2","text":"점수를 모두 곱하면 돼."},{"id":"3","text":"가장 높은 점수를 쓰면 돼."},{"id":"4","text":"점수를 모두 빼면 돼."}]', '1', 8.0, 50, NULL),
        (118, 3, 13, 'g56-l13', 'science', 'listening', 'advanced', NULL, '{"prompt":"전구가 켜지지 않은 이유가 아닌 것은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/science/listening/q13.mp3","stimulusText":"","promptSpans":[{"text":"전구가 켜지지 않은 이유가 ","style":"plain"},{"text":"아닌","style":"strong"},{"text":" 것은 무엇입니까?","style":"plain"}]}', '[{"id":"1","text":"전선이 끊어졌다."},{"id":"2","text":"전지가 없다."},{"id":"3","text":"전기회로에 전류가 통하지 않는다."},{"id":"4","text":"전구의 크기가 크다."}]', '4', 10.0, 51, NULL),
        (119, 3, 14, 'g56-l14', 'science', 'listening', 'advanced', NULL, '{"prompt":"지구에 대해 들려준 내용과 다른 것은 무엇입니까?","audioUrl":"/diagnostic-assets/g56/science/listening/q14.mp3","stimulusText":"","promptSpans":[{"text":"지구에 대해 들려준 내용과 ","style":"plain"},{"text":"다른","style":"strong"},{"text":" 것은 무엇입니까?","style":"plain"}]}', '[{"id":"1","text":"지구는 스스로 도는데 이것을 자전이라고 한다."},{"id":"2","text":"공전은 하루에 한 바퀴 도는 것이다."},{"id":"3","text":"지구는 태양 주위를 돈다."},{"id":"4","text":"자전 때문에 낮과 밤이 생긴다."}]', '2', 7.0, 52, NULL),
        (120, 3, 15, 'g56-l15', 'math', 'listening', 'advanced', NULL, '{"prompt":"파란 공이 나올 확률은 얼마입니까?","audioUrl":"/diagnostic-assets/g56/math/listening/q15.mp3","stimulusText":""}', '[{"id":"1","text":"오분의 이"},{"id":"2","text":"삼분의 이"},{"id":"3","text":"오분의 삼"},{"id":"4","text":"이분의 삼"}]', '3', 7.0, 53, NULL),
        (121, 3, 16, 'g56-r01', 'daily', 'reading', 'beginner', NULL, '{"prompt":"그림에 맞는 글자는 무엇입니까?","stimulusText":"","imageUrl":"/diagnostic-assets/g56/daily/reading/q01.png"}', '[{"id":"1","text":"가위"},{"id":"2","text":"가게"},{"id":"3","text":"가방"},{"id":"4","text":"가수"}]', '3', 4.0, NULL, 54),
        (122, 3, 17, 'g56-r02', 'daily', 'reading', 'beginner', NULL, '{"prompt":"그림에 맞는 글자는 무엇입니까?","stimulusText":"","imageUrl":"/diagnostic-assets/g56/daily/reading/q02.png"}', '[{"id":"1","text":"우산"},{"id":"2","text":"가방"},{"id":"3","text":"모자"},{"id":"4","text":"신발"}]', '1', 4.0, NULL, 55),
        (123, 3, 18, 'g56-r03', 'daily', 'reading', 'beginner', NULL, '{"prompt":"앞에 제시된 것과 가장 관계있는 것은 무엇입니까?","stimulusText":"","word":"급식실"}', '[{"id":"1","text":"약"},{"id":"2","text":"그림책"},{"id":"3","text":"공"},{"id":"4","text":"밥"}]', '4', 4.0, NULL, NULL),
        (124, 3, 19, 'g56-r04', 'science', 'reading', 'beginner', NULL, '{"prompt":"앞에 제시된 것과 가장 관계있는 것은 무엇입니까?","stimulusText":"","word":"바람"}', '[{"id":"1","text":"맵다"},{"id":"2","text":"차갑다"},{"id":"3","text":"짜다"},{"id":"4","text":"쓰다"}]', '2', 4.0, NULL, NULL),
        (125, 3, 20, 'g56-r05', 'social', 'reading', 'beginner', NULL, '{"prompt":"앞에 제시된 것과 가장 관계있는 것은 무엇입니까?","stimulusText":"","word":"대륙"}', '[{"id":"1","text":"밥을 먹는 곳."},{"id":"2","text":"그림책을 빌리는 곳."},{"id":"3","text":"아주 넓고 큰 땅."},{"id":"4","text":"운동을 하는 곳."}]', '3', 4.0, NULL, NULL),
        (126, 3, 21, 'g56-r06', 'daily', 'reading', 'beginner', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"식당"},{"id":"2","text":"학교"},{"id":"3","text":"서점"},{"id":"4","text":"문구점"}]', '1', 4.0, NULL, NULL),
        (127, 3, 22, 'g56-r07', 'daily', 'reading', 'beginner', NULL, '{"prompt":"그림을 바르게 설명한 것은 무엇입니까?","stimulusText":"","imageUrl":"/diagnostic-assets/g56/daily/reading/q07.png"}', '[{"id":"1","text":"그림책을 읽습니다."},{"id":"2","text":"노래를 부릅니다."},{"id":"3","text":"그림을 그립니다."},{"id":"4","text":"줄넘기를 합니다."}]', '4', 4.0, NULL, 56),
        (128, 3, 23, 'g56-r08', 'korean', 'reading', 'beginner', NULL, '{"prompt":"윗글과 가장 관계있는 말은 무엇입니까?","stimulusText":"나는 사진하고 그림을 친구들에게 보여 주었습니다. 그리고 앞에서 큰 소리로 말했습니다."}', '[{"id":"1","text":"생일"},{"id":"2","text":"발표"},{"id":"3","text":"시험"},{"id":"4","text":"여행"}]', '2', 4.0, NULL, NULL),
        (129, 3, 24, 'g56-r09', 'math', 'reading', 'beginner', NULL, '{"prompt":"앞에 제시된 것과 가장 관계있는 것은 무엇입니까?","stimulusText":"","word":"짝수, 홀수"}', '[{"id":"1","text":"모양"},{"id":"2","text":"과일"},{"id":"3","text":"수"},{"id":"4","text":"동물"}]', '3', 4.0, NULL, NULL),
        (130, 3, 25, 'g56-r10', 'daily', 'reading', 'beginner', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"내일 준비물과 숙제를 알려 주는 글이다."},{"id":"2","text":"친구를 생일 잔치에 초대하는 글이다."},{"id":"3","text":"학급 규칙을 소개하는 글이다."},{"id":"4","text":"수학 시험 날짜를 알리는 글이다."}]', '1', 4.0, NULL, NULL),
        (131, 3, 26, 'g56-r11', 'korean', 'reading', 'intermediate', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"㉯ → ㉱ → ㉰ → ㉮"},{"id":"2","text":"㉰ → ㉯ → ㉱ → ㉮"},{"id":"3","text":"㉰ → ㉱ → ㉯ → ㉮"},{"id":"4","text":"㉯ → ㉰ → ㉱ → ㉮"}]', '4', 6.0, NULL, NULL),
        (132, 3, 27, 'g56-r12', 'science', 'reading', 'intermediate', NULL, '{"prompt":"다음 글을 바르게 이해한 것은 무엇입니까?","stimulusText":"과학 시간에 선생님께서 오늘은 물이 얼음으로 변하는 과정을 관찰한다고 하셨다. 우리는 친구들과 함께 준비물을 챙기기로 했다. 그런데 상자를 열어 보니 얼음이 이미 다 녹아 있었다. 선생님께서는 “그러면 얼음이 녹는 모습을 관찰해 봅시다.”라고 하셨다. 우리는 계획을 바꾸어 실험을 했다."}', '[{"id":"1","text":"학생들은 물을 얼리는 실험을 했다."},{"id":"2","text":"실험 계획이 바뀌었다."},{"id":"3","text":"선생님께서 얼음을 준비하지 못하셨다."},{"id":"4","text":"친구들이 얼음을 녹여 버렸다."}]', '2', 6.0, NULL, NULL),
        (133, 3, 28, 'g56-r13', 'daily', 'reading', 'intermediate', NULL, '{"prompt":"나는 오늘 왜 지각할 뻔했습니까?","stimulusText":"나는 오늘 아침에 지각할 뻔했다. 시계 소리를 듣지 못하고 늦게 일어났기 때문이다. 급하게 가방을 챙기고 뛰어서 겨우 교문을 통과했다. 교문 앞에서 선생님께서는 웃으시면서 지각에 대해 “오늘은 괜찮아.”라고 말씀하셨다."}', '[{"id":"1","text":"가방을 잃어버려서."},{"id":"2","text":"버스를 놓쳐서."},{"id":"3","text":"시계 소리를 듣지 못해서."},{"id":"4","text":"선생님께 혼나서."}]', '3', 6.0, NULL, NULL),
        (134, 3, 29, 'g56-r14', 'math', 'reading', 'intermediate', NULL, '{"prompt":"우리 반 친구들이 좋아하는 과일에 대해 조사하여 표를 만들었습니다. 표를 바르게 이해한 것은 무엇입니까?","stimulusText":"","stimulusTable":{"headers":["과일","사과","딸기","포도","계"],"rows":[["학생 수(명)","10","6","4","20"],["백분율(%)","50","30","20","100"]]}}', '[{"id":"1","text":"사과를 좋아하는 학생의 백분율이 가장 높다."},{"id":"2","text":"딸기를 좋아하는 학생은 포도에 비해 적다."},{"id":"3","text":"포도를 좋아하는 학생은 전체의 30%이다."},{"id":"4","text":"사과를 좋아하는 학생은 딸기보다 적다."}]', '1', 6.0, NULL, NULL),
        (135, 3, 30, 'g56-r15', 'social', 'reading', 'intermediate', NULL, '{"prompt":"윗글의 중심 이야기는 무엇입니까?","stimulusText":"시장에서는 같은 물건이라도 가게에 따라 가격이 다르다. 그래서 우리는 가격과 품질을 비교하여 물건을 산다."}', '[{"id":"1","text":"시장에서는 모든 가게의 가격이 같다."},{"id":"2","text":"물건을 살 때 가격과 품질을 비교한다."},{"id":"3","text":"가격보다 가게 크기가 중요하다."},{"id":"4","text":"품질은 가격과 관계가 없다."}]', '2', 6.0, NULL, NULL),
        (136, 3, 31, 'g56-r16', 'korean', 'reading', 'advanced', NULL, '{"prompt":"윗글에서 밑줄 친 ㉮~㉱ 중 가리키는 것이 다른 하나는 무엇입니까?","stimulusText":"우리 반은 국어 시간에 ㉮토의를 했다. ㉯그것은 학교 규칙을 정하기 위한 시간이었다. 나는 ㉰그 토의에서 학교 규칙에 대해 내 의견을 말했다. 선생님께서는 ㉱그 규칙을 칠판에 쓰셨다.","promptSpans":[{"text":"윗글에서 밑줄 친 ㉮~㉱ 중 가리키는 것이 ","style":"plain"},{"text":"다른","style":"strong"},{"text":" 하나는 무엇입니까?","style":"plain"}],"stimulusSpans":[{"text":"우리 반은 국어 시간에 ","style":"plain"},{"text":"㉮토의","style":"underline"},{"text":"를 했다. ","style":"plain"},{"text":"㉯그것","style":"underline"},{"text":"은 학교 규칙을 정하기 위한 시간이었다. 나는 ","style":"plain"},{"text":"㉰그 토의","style":"underline"},{"text":"에서 학교 규칙에 대해 내 의견을 말했다. 선생님께서는 ","style":"plain"},{"text":"㉱그 규칙","style":"underline"},{"text":"을 칠판에 쓰셨다.","style":"plain"}]}', '[{"id":"1","text":"㉮"},{"id":"2","text":"㉯"},{"id":"3","text":"㉰"},{"id":"4","text":"㉱"}]', '4', 6.0, NULL, NULL),
        (137, 3, 32, 'g56-r17', 'social', 'reading', 'advanced', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"학교 급식 메뉴를 안내한다."},{"id":"2","text":"그림 대회 결과를 발표한다."},{"id":"3","text":"환경 보호 활동에 참여하도록 권유한다."},{"id":"4","text":"학급 회의 결과를 보고한다."}]', '3', 6.0, NULL, NULL),
        (138, 3, 33, 'g56-r18', 'social', 'reading', 'advanced', NULL, CONVERT(X'' USING utf8mb4), '[{"id":"1","text":"캠페인이 열리는 장소"},{"id":"2","text":"참여한 학생의 이름"},{"id":"3","text":"지난해 참여한 학생 수"},{"id":"4","text":"캠페인의 결과"}]', '1', 6.0, NULL, NULL),
        (139, 3, 34, 'g56-r19', 'korean', 'reading', 'advanced', NULL, '{"prompt":"윗글에서 주장이 가장 잘 드러난 부분은 어디입니까?","stimulusText":"㉮책을 읽으면 새로운 지식을 얻을 수 있다. ㉯독서는 지식과 경험을 주므로 우리는 매일 책을 읽어야 한다. ㉰이야기를 읽으며 여러 경험을 할 수 있다. ㉱실제로 책을 많이 읽은 학생은 글쓰기 점수가 높다는 조사 결과가 있다.","stimulusSpans":[{"text":"㉮책을 읽으면 새로운 지식을 얻을 수 있다.","style":"underline"},{"text":" ","style":"plain"},{"text":"㉯독서는 지식과 경험을 주므로 우리는 매일 책을 읽어야 한다.","style":"underline"},{"text":" ","style":"plain"},{"text":"㉰이야기를 읽으며 여러 경험을 할 수 있다.","style":"underline"},{"text":" ","style":"plain"},{"text":"㉱실제로 책을 많이 읽은 학생은 글쓰기 점수가 높다는 조사 결과가 있다.","style":"underline"}]}', '[{"id":"1","text":"㉮"},{"id":"2","text":"㉯"},{"id":"3","text":"㉰"},{"id":"4","text":"㉱"}]', '2', 6.0, NULL, NULL),
        (140, 3, 35, 'g56-r20', 'math', 'reading', 'advanced', NULL, '{"prompt":"윗글에서 알 수 있는 것은 무엇입니까?","stimulusText":"원의 둘레를 원주라고 한다. 원주를 지름으로 나눈 값을 원주율이라고 한다. 원주율은 원의 크기가 달라도 항상 같으므로 약 3.14로 나타낸다."}', '[{"id":"1","text":"원주율은 원의 크기에 따라 달라진다."},{"id":"2","text":"원주는 원의 넓이를 뜻한다."},{"id":"3","text":"원주율은 지름에 원주를 곱한 값이다."},{"id":"4","text":"원주를 지름으로 나눈 값이 원주율이다."}]', '4', 6.0, NULL, NULL);
