-- Select the empty development database in HeidiSQL or the MariaDB CLI before running.
-- Run this entire file once. MariaDB 11.8. Development fixtures only.
SET NAMES utf8mb4;
SET SESSION time_zone = '+00:00';
SET @seed_now = UTC_TIMESTAMP(6);

DELIMITER //
BEGIN NOT ATOMIC
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    START TRANSACTION;
    IF EXISTS (SELECT 1 FROM users LIMIT 1) OR EXISTS (SELECT 1 FROM diagnostic_forms LIMIT 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Seed requires an empty development database.';
    END IF;





